(()=>{'use strict';
const C=window.DeskCore,$=s=>document.querySelector(s),E=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const S={project:C.newProject(),projects:[],view:'overview',boardMode:'board',page:'',section:'',draft:'',month:new Date(new Date().getFullYear(),new Date().getMonth(),1),dirty:false,saving:false,saveError:'',revision:0,savedRevision:0,history:null,info:null,jobs:[],preview:'',previewRevision:-1,previewPage:'',buildId:'',mobile:false,busyBuild:false,pendingBuild:false,closing:false};
let saveTimer=0,buildTimer=0,toastTimer=0,pollTimer=0,initialized=false,integrationHandle=null;const bridge=()=>window.studioDesk,tr=(z,e)=>S.project.settings.language==='en'?e:z,lang=()=>S.project.settings.language==='en'?'en-GB':'zh-CN',now=()=>new Date().toISOString(),dateLocal=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const navs=[['overview','◉','项目总览','Overview'],['workspace','◎','目标与验收','Brief & acceptance'],['operations','▦','任务与日程','Tasks & calendar'],['bom','▤','物料清单','Bill of materials'],['screen','▣','屏幕设计','Screen design'],['environment','⌘','环境准备','Environment'],['drafts','≡','内容草稿','Drafts'],['site','◇','网站编辑','Website'],['resources','⌁','项目资料','References'],['jobs','↻','任务记录','Jobs'],['publish','↗','发布与域名','Publish'],['settings','⚙','偏好设置','Settings'],['help','?','关于与帮助','About & help']];
const status=v=>({idea:tr('待安排','Ideas'),doing:tr('进行中','In progress'),review:tr('待检查','Review'),done:tr('已完成','Done'),running:tr('执行中','Running'),failed:tr('失败','Failed'),cancelled:tr('已取消','Cancelled')})[v]||v;
const channel=v=>({web:tr('网站','Website'),wechat:tr('公众号','WeChat'),canva:'Canva',event:tr('活动','Event'),other:tr('其他','Other')})[v]||v;
const type=v=>({hero:tr('首屏','Hero'),text:tr('正文','Text'),cards:tr('卡片','Cards'),gallery:tr('图片集','Gallery'),faq:tr('问答','FAQ'),cta:tr('行动引导','Call to action'),contact:tr('联系','Contact')})[v]||v;
const taskName=v=>({handoff:tr('项目交接包（含私有资料）','Project handoff (private data)'),build:tr('构建网站','Build website'),audit:tr('检查网站','Audit website'),backup:tr('完整项目备份','Project backup'),calendar:tr('导出日历','Export calendar'),drafts:tr('导出草稿','Export drafts'),deploy:tr('发布网站','Deploy website'),dns:tr('检查域名DNS','Check domain DNS')})[v]||v;
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),4200);}
function messageText(value){const text=String(value??'');if(/[\u3400-\u9fff]/.test(text)&&text.includes(' / ')){const parts=text.split(' / ');return S.project.settings.language==='en'?parts.slice(1).join(' / '):parts[0];}return text;}
function niceError(e){return tr('操作未完成：','Action not completed: ')+messageText(e?.message||e||'ERROR').slice(0,600);}
function selectOptions(values,current,labels=x=>x){return values.map(v=>`<option value="${E(v)}" ${v===current?'selected':''}>${E(labels(v))}</option>`).join('');}
function button(action,label,cls='',extra=''){return`<button type="button" data-action="${action}" class="${cls}" ${extra}>${label}</button>`;}
function field(label,path,value,kind='text',max=160,extra=''){return`<label>${label}${kind==='textarea'?`<textarea data-field="${E(path)}" maxlength="${max}" ${extra}>${E(value)}</textarea>`:`<input data-field="${E(path)}" type="${kind}" value="${E(value)}" maxlength="${max}" ${extra}>`}</label>`;}
function getPage(){return S.project.site.pages.find(p=>p.id===S.page)||S.project.site.pages[0];}function getSection(){return getPage()?.sections.find(s=>s.id===S.section)||getPage()?.sections[0];}function getDraft(){return S.project.operations.drafts.find(d=>d.id===S.draft)||S.project.operations.drafts[0];}
function setPath(obj,path,value){const parts=path.split('.');let target=obj;for(const key of parts.slice(0,-1)){if(['__proto__','prototype','constructor'].includes(key)||!Object.hasOwn(target,key))throw Error('FIELD_PATH');target=target[key];}const key=parts.at(-1);if(['__proto__','prototype','constructor'].includes(key)||!Object.hasOwn(target,key))throw Error('FIELD_PATH');target[key]=value;}
function scheduleSave(){clearTimeout(saveTimer);if(!bridge()){S.saveError=tr('浏览器会话：请导出项目保存','Browser session: export your project to save');updateSave();return;}saveTimer=setTimeout(()=>save().catch(e=>{S.saveError=niceError(e);updateSave();}),650);}
function change(fn,{renderPage=true,remember=true,site=false}={}){const next=C.clone(S.project);fn(next);next.updatedAt=now();S.project=next;S.dirty=true;S.revision++;if(remember)try{S.history.push(next);}catch{}scheduleSave();if(site&&S.project.settings.autoBuild){clearTimeout(buildTimer);buildTimer=setTimeout(()=>runJob('build',{pageSlug:getPage().slug},true).catch(e=>toast(niceError(e))),1600);}if(renderPage)render();else updateSave();}
async function save(){if(integrationHandle?.flush)await integrationHandle.flush();clearTimeout(saveTimer);if(!S.dirty&&!S.migrated)return true;if(S.saving){await new Promise(resolve=>setTimeout(resolve,90));return save();}if(!bridge())throw Error(tr('当前只是浏览器会话，请先导出完整项目','Browser session only: export the complete project first'));const project=C.validate(S.project),revision=S.revision;S.saving=true;S.saveError='';updateSave();try{const result=await bridge().save(project);if(!result?.saved||result.id!==project.id)throw Error('SAVE_CONTRACT');if(S.revision===revision){S.project=project;S.project.updatedAt=result.updatedAt||project.updatedAt;S.dirty=false;S.migrated=false;S.savedRevision=revision;}S.projects=S.projects.filter(x=>x.id!==project.id);S.projects.unshift({id:project.id,name:project.name,updatedAt:result.updatedAt||project.updatedAt});return true;}catch(e){S.saveError=niceError(e);throw e;}finally{S.saving=false;updateSave();if(S.dirty&&S.revision!==revision)scheduleSave();}}
function updateSave(){const e=$('[data-save-state]');if(e){e.textContent=S.saveError||S.saving?S.saveError||tr('正在保存…','Saving…'):S.migrated?tr('旧项目已读取；保存后升级格式','Older project loaded; save to upgrade'):S.dirty?tr('有未保存修改','Unsaved changes'):tr('已保存在本机','Saved on this device');e.classList.toggle('error',!!S.saveError);}const undo=$('[data-action=undo]'),redo=$('[data-action=redo]');if(undo)undo.disabled=!S.history?.canUndo;if(redo)redo.disabled=!S.history?.canRedo;const copySite=$('[data-action=copy-site]');if(copySite)copySite.disabled=!bridge()||!S.buildId;const buildButton=$('[data-action=build]');if(buildButton){buildButton.disabled=!bridge()||S.busyBuild||S.jobs.some(j=>j.status==='running');buildButton.setAttribute('aria-busy',String(S.busyBuild));}const deploy=$('[data-action=deploy]');if(deploy){deploy.disabled=!bridge()||!S.buildId||S.previewRevision!==S.revision;deploy.title=S.previewRevision!==S.revision?tr('请先构建当前内容并检查预览','Build and inspect the current content first'):'';}const stale=$('[data-preview-stale]');if(stale)stale.textContent=S.preview&&S.previewRevision!==S.revision?tr('内容已修改，预览仍是上次构建。点击“构建预览”更新。','Content changed. This is the previous build; build the preview again.') :S.preview?tr('预览来自实际 Python 构建结果。','Preview comes from the actual Python build.') :tr('还没有构建结果。编辑完成后构建预览。','No build yet. Edit the content, then build a preview.');}
async function leaveProject(){if(integrationHandle?.flush)await integrationHandle.flush();if(!S.dirty)return true;if(bridge()){try{await save();return true;}catch(e){toast(niceError(e));return false;}}return window.confirm(tr('当前项目尚未导出。继续将离开这些修改，是否继续？','This project has not been exported. Continue and leave these changes?'));}
function adopt(project,{dirty=false}={}){clearTimeout(saveTimer);clearTimeout(buildTimer);S.migrated=project.schema===1;S.project=C.validate(project);S.history=new C.History(S.project);S.page=S.project.site.pages[0].id;S.section='';S.draft='';S.dirty=dirty;S.revision=0;S.savedRevision=0;S.preview='';S.previewRevision=-1;S.previewPage='';S.buildId='';S.saveError='';if(dirty){S.revision++;scheduleSave();}render();}
async function loadProject(id){if(id===S.project.id)return;if(!await leaveProject()){render();return;}adopt(await bridge().load(id));}
function download(name,data,mime='application/json'){const blob=new Blob([typeof data==='string'?data:JSON.stringify(data,null,2)],{type:mime}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function exportProject(){const p=C.validate(S.project),result=bridge()?await bridge().exportProject(p):(download(p.name.replace(/[<>:"/\\|?*]/g,'_')+'.zthdesk',p),{path:'browser'});if(result){toast(tr('完整项目已导出，包含私有任务、草稿与图片。','Complete project exported, including private tasks, drafts and images.'));if(!bridge()){S.dirty=false;S.saveError='';updateSave();}}}
async function runJob(task,options={},automatic=false){if(!bridge())throw Error(tr('真实任务需要 Studio Desk 桌面客户端','Real tasks require the Studio Desk desktop client'));const project=C.validate(S.project);if(task==='build'&&(S.busyBuild||S.jobs.some(j=>j.status==='running'))){if(automatic)S.pendingBuild=true;else toast(tr('构建正在进行，请等待结果。','A build is already running. Wait for its result.'));return;}if(task==='build')S.busyBuild=true;try{const result=await bridge().run({task,project,options});if(result?.cancelled){if(!automatic)toast(tr('已取消，未开始新任务。','Cancelled. No new task started.'));if(task==='build')S.busyBuild=false;return;}if(!result?.id)throw Error('JOB_CONTRACT');S.jobs.unshift({id:result.id,task,status:'running',startedAt:now(),_revision:S.revision,_projectId:project.id,_page:options.pageSlug||'index'});if(!automatic)toast(tr('任务已开始，可在任务记录查看。','Task started. See Jobs for its result.'));startPolling();updateSave();if(S.view==='jobs'||S.view==='publish')render();}catch(e){if(task==='build')S.busyBuild=false;updateSave();throw e;}finally{if(Object.hasOwn(options,'token'))options.token='';}}
function startPolling(){if(pollTimer)return;pollTimer=setTimeout(pollJobs,450);}
async function pollJobs(){pollTimer=0;for(const job of S.jobs.filter(j=>j.status==='running')){try{const state=await bridge().job(job.id);Object.assign(job,state);if(state.status==='done'&&job.task==='build'){S.busyBuild=false;if(job._projectId===S.project.id&&typeof state.result?.previewHtml==='string'){S.preview=state.result.previewHtml;S.previewRevision=job._revision;S.previewPage=job._page;S.buildId=job.id;showPreview();}}if(['failed','cancelled'].includes(state.status)&&job.task==='build')S.busyBuild=false;}catch(e){job.status='failed';job.error={message:String(e.message||e)};if(job.task==='build')S.busyBuild=false;}}if(S.view==='jobs')render();if(S.jobs.some(j=>j.status==='running'))startPolling();else if(S.pendingBuild&&S.project.settings.autoBuild){S.pendingBuild=false;runJob('build',{pageSlug:getPage().slug},true).catch(e=>toast(niceError(e)));}updateSave();}
function showPreview(){const iframe=$('#site-preview');if(iframe&&S.preview)iframe.srcdoc=S.preview;const slot=$('[data-preview-slot]');if(slot){slot.innerHTML=S.preview?'<iframe id="site-preview" sandbox="" referrerpolicy="no-referrer" title="'+E(tr('隔离网站预览','Sandboxed website preview'))+'"></iframe>':`<div class="preview-placeholder"><strong>${tr('从内容开始。','Start with the content.')}</strong>${tr('左侧组织页面与区块，右侧编辑文字和图片。构建后，这里显示真实生成的网站。','Organise pages and sections on the left; edit text and images on the right. Build to see the generated website here.')}</div>`;if(S.preview)$('#site-preview').srcdoc=S.preview;}updateSave();}
function head(title,sub,actions=''){return`<div class="page-head"><div><p class="eyebrow">ZTH STUDIO DESK · ${tr('工作室的日常','A PLACE FOR THE DAILY WORK')}</p><h1>${title}</h1><p class="subtitle">${sub}</p></div><div class="actions">${actions}</div></div>`;}
function render(){if(integrationHandle){try{typeof integrationHandle==='function'?integrationHandle():integrationHandle.dispose?.();}catch{}integrationHandle=null;}const publishInputs=S.view==='publish'&&$('#publish-owner')?{owner:$('#publish-owner').value,repo:$('#publish-repo').value,token:$('#publish-token').value,consent:$('#publish-consent').checked}:null;const p=S.project;document.documentElement.lang=p.settings.language==='en'?'en':'zh-CN';document.documentElement.dataset.theme=p.settings.theme;document.title=p.name+' · ZTH Studio Desk';const all=S.projects.some(x=>x.id===p.id)?S.projects:[{id:p.id,name:p.name},...S.projects];$('#app').innerHTML=`<div class="app-shell"><aside class="sidebar"><div class="brand"><img src="logo.svg" alt="ZTH"><div><strong>${tr('赋形造物工作台','Studio Desk')}</strong><small>DEFINE · MAKE · SHARE</small></div></div><nav class="nav-group" aria-label="${tr('主导航','Main navigation')}"><span>${tr('工作空间','WORKSPACE')}</span>${navs.map(([v,icon,z,e])=>`<button class="nav-btn ${S.view===v?'active':''}" data-view="${v}" ${S.view===v?'aria-current="page"':''}><b aria-hidden="true">${icon}</b>${tr(z,e)}</button>`).join('')}</nav><div class="sidebar-foot"><p><i class="privacy-dot"></i>${tr('本地优先 · 数据由你保管','Local first · Your data stays yours')}</p><small>2.0.0 · ${tr('理工阿白菌','TechABJ')}</small></div></aside><header class="topbar"><div class="project-picker"><select data-project aria-label="${tr('选择项目','Select project')}">${all.map(x=>`<option value="${E(x.id)}" ${x.id===p.id?'selected':''}>${E(x.name||tr('未命名','Untitled'))}</option>`).join('')}</select>${button('new-project','＋','quiet','aria-label="'+tr('新建项目','New project')+'"')}</div><div class="top-actions"><span class="save-state" data-save-state></span>${button('language',tr('EN','中文'),'quiet')}${button('save',tr('保存','Save'),'quiet')}${button('export-project',tr('导出项目','Export project'),'primary')}</div></header><main id="main" tabindex="-1">${({overview:overview2,workspace:workspaceView,bom:bomView,resources:resourcesView,screen:()=>integrationView('screen'),environment:()=>integrationView('environment'),operations:operations,drafts:drafts,site:site,jobs:jobs,publish:publish,settings:settings,help:help2}[S.view]||overview2)()}</main></div>`;showPreview();updateSave();mountIntegration();if(publishInputs&&$('#publish-owner')){$('#publish-owner').value=publishInputs.owner;$('#publish-repo').value=publishInputs.repo;$('#publish-token').value=publishInputs.token;$('#publish-consent').checked=publishInputs.consent;}}
function empty(title,body,action){return`<div class="empty"><h3>${title}</h3><p>${body}</p>${action?button(action,tr('开始创建','Create your first')):''}</div>`;}
function taskRow(t){return`<div class="row"><div><h3>${E(t.title)}</h3><p>${E(t.due||tr('未定日期','No date'))} · ${channel(t.channel)}${t.owner?' · '+E(t.owner):''}</p>${taskTargetButton(t)}</div><button data-edit-task="${E(t.id)}"><span class="badge">${status(t.status)}</span></button></div>`;}
function operations(){return head(tr('一眼看清，手头的事。','A clear view of what is next.'),tr('任务与月日历共享同一份私有计划。点击日期添加任务。','The board and calendar share your private plan. Click a date to add a task.'),button('new-task',tr('＋ 新建任务','＋ New task'),'primary'))+`<div class="card-head"><div class="mode-switch">${['board','calendar'].map(m=>button('board-mode',m==='board'?tr('看板','Board'):tr('月日历','Month'),S.boardMode===m?'selected':'',`data-mode="${m}"`)).join('')}</div><div class="actions">${button('run-calendar',tr('导出 ICS 日历','Export ICS'),'',!bridge()?'disabled':'')}${S.boardMode==='calendar'?button('month-prev','←')+`<strong style="font-size:14px">${E(S.month.toLocaleDateString(lang(),{year:'numeric',month:'long'}))}</strong>`+button('month-next','→'):''}</div></div>`+(S.boardMode==='calendar'?calendar():`<div class="board">${['idea','doing','review','done'].map(st=>{const tasks=S.project.operations.tasks.filter(x=>x.status===st);return`<section class="board-col"><header><span>${status(st)}</span><i>${tasks.length}</i></header>${tasks.map(t=>`<article class="task-card"><button class="task-title" data-edit-task="${E(t.id)}">${E(t.title)}</button><div class="task-meta"><span>${channel(t.channel)}</span><span>${E(t.due||tr('日期未定','Undated'))}</span>${t.owner?`<span>${E(t.owner)}</span>`:''}</div><select data-task-status="${E(t.id)}" aria-label="${tr('任务状态','Task status')}">${selectOptions(['idea','doing','review','done'],st,status)}</select>${taskTargetButton(t)}</article>`).join('')||`<small>${tr('暂时没有任务','No tasks yet')}</small>`}</section>`;}).join('')}</div>`);}
function calendar(){const start=new Date(S.month.getFullYear(),S.month.getMonth(),1),offset=(start.getDay()+6)%7;start.setDate(start.getDate()-offset);const days=Array.from({length:42},(_,i)=>new Date(start.getFullYear(),start.getMonth(),start.getDate()+i));return`<div class="calendar"><div class="calendar-head">${(S.project.settings.language==='en'?['MON','TUE','WED','THU','FRI','SAT','SUN']:['周一','周二','周三','周四','周五','周六','周日']).map(s=>`<span>${s}</span>`).join('')}</div><div class="calendar-grid">${days.map(day=>{const key=dateLocal(day),items=S.project.operations.tasks.filter(t=>t.due===key);return`<div class="calendar-cell ${day.getMonth()!==S.month.getMonth()?'other':''} ${key===dateLocal(new Date())?'today':''}"><button class="day-button" data-add-date="${key}" aria-label="${key}">${day.getDate()}</button>${items.slice(0,4).map(t=>`<button class="cal-task" data-edit-task="${E(t.id)}" title="${E(t.title)}">${E(t.title)}</button>`).join('')}${items.length>4?`<small>+${items.length-4}</small>`:''}</div>`;}).join('')}</div></div>`;}
function drafts(){const d=getDraft(),index=S.project.operations.drafts.findIndex(x=>x.id===d?.id);return head(tr('先写好，再决定公开。','Write first. Share when ready.'),tr('草稿是私有资料，不会混进网站导出或 Pages 提交。','Drafts are private. They never enter website exports or Pages commits.'),button('new-draft',tr('＋ 新建草稿','＋ New draft'),'primary')+button('run-drafts',tr('导出 Markdown','Export Markdown'),'',!bridge()?'disabled':''))+`<div class="drafts-layout"><div class="draft-list">${S.project.operations.drafts.map(x=>`<button class="draft-item ${x.id===d?.id?'selected':''}" data-open-draft="${E(x.id)}"><strong>${E(x.title)}</strong><small>${E(x.tags.join(' · ')||tr('无标签','No tags'))}</small></button>`).join('')||empty(tr('还没有草稿','No drafts yet'),tr('留住第一个想法。','Capture the first thought.'),'new-draft')}</div>${d?`<section class="card stack">${field(tr('标题','Title'),'operations.drafts.'+index+'.title',d.title)}${field(tr('正文 · 私有','Body · private'),'operations.drafts.'+index+'.body',d.body,'textarea',64000,'class="editor-text"')}<label>${tr('标签（逗号分隔）','Tags (comma-separated)')}<input data-draft-tags="${E(d.id)}" value="${E(d.tags.join(', '))}" maxlength="800"></label><div class="actions"><span class="badge private">${tr('仅在完整项目中保存','Saved only in the full project')}</span>${button('delete-draft',tr('删除草稿','Delete draft'),'danger')}</div></section>`:''}</div>`;}
function imageOptions(current){return`<option value="">${tr('不使用图片','No image')}</option>`+S.project.site.assets.map(a=>`<option value="${E(a.id)}" ${a.id===current?'selected':''}>${E(a.name)}</option>`).join('');}
function site(){const p=getPage(),s=getSection(),pi=S.project.site.pages.indexOf(p),si=p.sections.indexOf(s),path='site.pages.'+pi+'.sections.'+si;return head(tr('把工作室，好好介绍。','A considered home for your studio.'),tr('只编辑公开网站内容。私有运营资料不会自动带入。','Edit public website content only. Private operations are never included automatically.'))+`<div class="site-actions"><div class="actions">${button('undo','↶ '+tr('撤销','Undo'))}${button('redo','↷ '+tr('重做','Redo'))}${button('site-settings',tr('网站设置','Site settings'))}${button('assets',tr('图片素材','Images'))}</div><div class="actions">${button('run-audit',tr('检查','Audit'),'',!bridge()?'disabled':'')}${button('build',tr('构建预览','Build preview'),'primary',!bridge()?'disabled':'')}${button('copy-site',tr('保存网站 ZIP','Save website ZIP'),'',!S.buildId?'disabled':'')}</div></div><div class="site-grid"><aside class="site-outline"><h3>${tr('页面与区块','PAGES & SECTIONS')}</h3>${S.project.site.pages.map(x=>`<button class="page-link ${x.id===p.id?'active':''}" data-page="${E(x.id)}">${E(x.title)} <small>${E(x.slug)}</small></button>`).join('')}<div class="actions" style="margin:12px 0">${button('new-page',tr('＋ 页面','＋ Page'))}${button('edit-page',tr('设置','Settings'))}</div><div class="sections-list">${p.sections.map(x=>`<button class="section-link ${x.id===s?.id?'selected':''}" data-section="${E(x.id)}"><span>${type(x.type)}</span>${E(x.title||tr('未命名区块','Untitled section'))}</button>`).join('')||`<small>${tr('这个页面还是空白。','This page is still blank.')}</small>`}</div>${button('new-section',tr('＋ 添加区块','＋ Add section'))}</aside><div class="preview-area"><div class="preview-toolbar"><span>${E(S.previewPage?S.previewPage+'.html':p.slug+'.html')} · ${tr('隔离预览','Sandbox preview')}</span><div class="actions">${button('preview-width',tr('桌面','Desktop'),!S.mobile?'selected':'','data-mobile="false"')}${button('preview-width',tr('手机','Mobile'),S.mobile?'selected':'','data-mobile="true"')}</div></div><div class="preview-frame ${S.mobile?'mobile':''}" data-preview-slot></div><p class="preview-stale" data-preview-stale></p>${!bridge()?`<div class="help-note">${tr('浏览器会话不含 Python 引擎。请在桌面客户端构建真实网站；这里不会用模拟页面冒充构建结果。','This browser session has no Python engine. Use the desktop client to build the real website; no simulated result is substituted here.')}</div>`:''}</div><aside class="inspector"><h3>${s?type(s.type):tr('区块属性','SECTION DETAILS')}</h3>${s?`${field(tr('标题','Title'),path+'.title',s.title)}${field(tr('正文 · 纯文本','Body · plain text'),path+'.body',s.body,'textarea',16000)}<label>${tr('图片','Image')}<select data-field="${path}.image">${imageOptions(s.image)}</select></label>${field(tr('链接 · HTTPS / 页面.html','Link · HTTPS / page.html'),path+'.link',s.link,'text',2048)}${field(tr('链接按钮文字','Link label'),path+'.label',s.label)}<div class="actions">${button('section-up','↑ '+tr('上移','Up'))}${button('section-down','↓ '+tr('下移','Down'))}${button('delete-section',tr('删除','Delete'),'danger')}</div>${['cards','gallery','faq'].includes(s.type)?s.items.map((item,i)=>`<div class="item-editor"><small>${tr('条目','Item')} ${i+1}</small>${field(tr('标题','Title'),path+'.items.'+i+'.title',item.title)}${field(tr('正文','Body'),path+'.items.'+i+'.body',item.body,'textarea',16000)}<label>${tr('图片','Image')}<select data-field="${path}.items.${i}.image">${imageOptions(item.image)}</select></label>${field(tr('链接','Link'),path+'.items.'+i+'.link',item.link,'text',2048)}${button('delete-item',tr('移除条目','Remove item'),'danger',`data-index="${i}"`)}</div>`).join('')+button('new-item',tr('＋ 添加条目','＋ Add item')):''}`:empty(tr('从一个区块开始','Start with a section'),tr('首屏、正文、图片或问答。','A hero, text, images or FAQ.'),'new-section')}</aside></div>`;}
function jobs(){return head(tr('每一步，都有结果。','A record of each step.'),tr('本机任务记录不保存令牌或私有正文。取消不会撤销已完成的远端提交。','Local job records exclude tokens and private bodies. Cancel does not undo completed remote commits.'),button('refresh-jobs',tr('刷新记录','Refresh')))+`<div class="actions" style="margin-bottom:20px">${button('run-backup',tr('创建完整备份','Create full backup'),'',!bridge()?'disabled':'')}${button('run-calendar',tr('导出私有日历','Export private calendar'),'',!bridge()?'disabled':'')}${button('run-drafts',tr('导出私有草稿','Export private drafts'),'',!bridge()?'disabled':'')}</div>${S.jobs.length?S.jobs.map(jobCard).join(''):empty(tr('还没有任务记录','No jobs yet'),tr('第一次构建、导出或检查会记录在这里。','Your first build, export or audit will appear here.'))}`;}
function jobCard(j){const report=j.result?.report,summary=messageText(j.error?typeof j.error==='string'?j.error:j.error.message:j.result?.message||j.result?.status||'');return`<article class="job"><div class="job-head"><div><h3>${taskName(j.task)}</h3><small>${E(j.startedAt?new Date(j.startedAt).toLocaleString(lang()):j.id)}</small></div><span class="badge ${j.status==='failed'?'warn':''}">${status(j.status)}</span></div>${summary?`<div class="job-results">${E(summary)}</div>`:''}${report?`<div class="job-results">${E(tr('错误：','Errors: ')+(report.errors||[]).length+' · '+tr('提示：','Warnings: ')+(report.warnings||[]).length+'\n'+[...(report.errors||[]),...(report.warnings||[])].map(x=>typeof x==='string'?x:x.message||JSON.stringify(x)).join('\n'))}</div>`:''}${j.task==='deploy'&&j.result?`<div class="job-results">${E(tr('文件已上传：','Files uploaded: ')+String(!!j.result.uploaded)+' · Pages '+(j.result.pagesStatus||'unknown')+'\n'+tr('已核验上线：','Verified live: ')+String(!!j.result.live)+'\n'+(j.result.url||''))}</div>`:''}${j.task==='dns'&&j.result?`<div class="job-results">${E((j.result.domain||'')+'\n'+(j.result.addresses||[]).join('\n')+'\n'+tr('解析成功：','Resolved: ')+String(!!j.result.resolved)+' · '+tr('匹配Pages地址：','Matches Pages address: ')+String(!!j.result.matchesGithubPagesAddress))}</div>`:''}${j.result?.files?`<small>${j.result.files.length} ${tr('个公开网站文件','public website files')}</small>`:''}<div class="actions">${j.status==='running'?`<button data-cancel-job="${E(j.id)}">${tr('请求取消','Request cancellation')}</button>`:j.status==='done'?`<button data-open-job="${E(j.id)}">${tr('打开输出位置','Open output')}</button>${j.result?.artifactPath||j.result?.zipPath||j.result?.path?`<button data-copy-job="${E(j.id)}">${tr('另存输出文件','Save output as')}</button>`:''}`:''}</div></article>`;}
function hostingGuide(){return `<details class="hosting-guide card"><summary>${tr('第一次发布：仓库、托管与域名怎么连接？','First publish: repository, hosting and domain')}</summary><div class="stack" style="margin-top:18px"><h3>GitHub Pages</h3><ol class="prose"><li>${tr('在 GitHub 新建仓库，勾选添加 README 完成初始化，再填写上方所有者与仓库名。','Create a GitHub repository with a README to initialise it, then enter its owner and name above.')}</li><li>${tr('构建检查网站，填写本次令牌，确认公开范围后点击发布。在任务记录查看结果。','Build and inspect the website. Enter an invocation token, confirm the public scope and publish. Check Jobs for the result.')}</li><li>${tr('打开仓库 Settings → Pages。若提示需要配置，选择 Deploy from a branch → zth-site → / (root)，保存并等待部署。','Open repository Settings → Pages. If configuration is required, choose Deploy from a branch → zth-site → / (root), save and wait.')}</li><li>${tr('先在 Pages 的 Custom domain 添加你控制的域名，再修改 DNS。子域名（如 www.example.com）创建 CNAME，目标为：','Add a domain you control under Pages → Custom domain before changing DNS. For a subdomain such as www.example.com, create a CNAME pointing to:')} <code data-cname-target>your-account.github.io</code> ${tr('（不含仓库路径）。','(without a repository path).')}</li><li>${tr('根域名的 A / AAAA 或 ALIAS / ANAME 按官方表格配置。待 DNS 与证书就绪，再检查 HTTPS。DNS 查询成功不等于网站已上线。','For an apex domain, use the official A / AAAA or ALIAS / ANAME records. Check HTTPS once DNS and the certificate are ready. A successful DNS query alone does not mean the site is live.')}</li></ol>${button('external',tr('GitHub 域名配置步骤','GitHub domain setup'),'', 'data-url="https://docs.github.com/en/pages/configuring-a-custom-domain-for-your-github-pages-site/managing-a-custom-domain-for-your-github-pages-site"')}<h3>Cloudflare Pages</h3><p class="prose">${tr('也可先保存网站 ZIP，在 Cloudflare Pages 新建 Direct Upload 项目，拖入网站 ZIP 并部署；然后在项目的 Custom domains 添加域名，按平台提示配置 DNS。本工具不调用 Cloudflare API，也不会代你更改 DNS。','Alternatively, save the website ZIP, create a Cloudflare Pages Direct Upload project, drag in the ZIP and deploy. Add your domain under Custom domains and follow its DNS instructions. This app does not call the Cloudflare API or change DNS for you.')}</p><div class="actions">${button('external',tr('直接上传说明','Direct Upload guide'),'', 'data-url="https://developers.cloudflare.com/pages/get-started/direct-upload/"')}${button('external',tr('Cloudflare 域名说明','Cloudflare custom domains'),'', 'data-url="https://developers.cloudflare.com/pages/configuration/custom-domains/"')}</div></div></details>`;}
function publish(){const last=S.jobs.find(j=>j.id===S.buildId),report=last?.result?.report;return head(tr('先检查，再让别人看见。','Review it. Then make it public.'),tr('发布需要网络和原生确认。仅公开网站文件会进入专用 zth-site 分支。','Publishing needs network access and native confirmation. Only public site files enter the dedicated zth-site branch.'))+`<div class="publish-layout"><section class="card stack"><h2>GitHub Pages</h2><div class="form-grid"><label>${tr('仓库所有者','Repository owner')}<input id="publish-owner" autocomplete="off" maxlength="100" placeholder="your-account"></label><label>${tr('仓库名','Repository')}<input id="publish-repo" autocomplete="off" maxlength="100" placeholder="studio-site"></label><label class="span2">${tr('本次使用的访问令牌','Access token for this invocation')}<input id="publish-token" type="password" autocomplete="new-password" spellcheck="false" maxlength="300"></label></div><p class="help-note">${tr('令牌只用于你这一次点击，不保存进项目或历史。发布前核对仓库权限与公开范围，不要在草稿、网站文字或截图里放令牌。','The token is used only for this click and is not saved in the project or history. Review repository permissions and public scope; never put a token in drafts, site text or screenshots.')}</p><label class="check"><input type="checkbox" id="publish-consent">${tr('我已检查网站内容，同意将网站文件公开发布到所填仓库。','I reviewed the website and agree to publish its files to this repository.')}</label><div class="actions">${button('build',tr('先构建检查','Build first'))}${button('deploy',tr('审阅并发布','Review & publish'),'primary',!bridge()||!S.buildId?'disabled':'')}</div><small>${tr('现有未标记的 zth-site 分支会被拒绝，不覆盖源代码 main。上传成功和 Pages 已上线是不同状态。','An unmarked existing zth-site branch is refused; source main is untouched. Upload success and a live Pages site are distinct states.')}</small></section><section class="stack"><div class="ready-panel"><h3>${tr('公开范围','Public scope')}</h3><p class="prose">${S.project.site.pages.length} ${tr('页','pages')} · ${S.project.site.assets.length} ${tr('张主动加入网站的图片','images explicitly added to the site')}</p><ul class="publish-list"><li>${tr('包含：网页、样式、网站图片与站点文件','Included: pages, styles, site images and site files')}</li><li>${tr('不包含：运营任务、负责人、草稿、完整项目','Excluded: tasks, owners, drafts and complete project')}</li></ul>${last?`<p class="prose">${tr('上次构建文件数：','Files in the previous build: ')}${last.result?.files?.length||0} · ${tr('错误：','Errors: ')}${report?.errors?.length||0}</p>`:''}</div><div class="card stack"><h2>${tr('域名与路径','Domain & path')}</h2>${field(tr('自定义域名（仅主机名）','Custom domain (hostname only)'),'site.domain',S.project.site.domain,'text',253,'placeholder="example.com"')}${field(tr('仓库子路径（可空）','Repository subpath (optional)'),'site.basePath',S.project.site.basePath,'text',100,'placeholder="/studio-site/"')}<div class="actions">${button('dns',tr('主动查询 DNS','Query DNS'),'',!bridge()||!S.project.site.domain?'disabled':'')}${button('external',tr('Pages 官方说明','Pages documentation'),'', 'data-url="https://docs.github.com/en/pages"')}</div><small>${tr('DNS 查询只观察当前解析，不证明域名所有权、证书或全球传播完成。不会自动扫描。','DNS observes current records, not domain ownership, TLS readiness or worldwide propagation. No automatic scans.')}</small></div></section></div>${hostingGuide()}`;}
function settings(){return head(tr('让工具，适合你的习惯。','A workspace that feels like yours.'),tr('偏好随完整项目保存。自动构建仅在应用打开时工作，不创建系统计划任务。','Preferences travel with the complete project. Auto-build runs only while the app is open; no OS scheduled task is created.'))+`<div class="settings-grid"><section class="card stack"><h2>${tr('工作空间','Workspace')}</h2>${field(tr('项目名称','Project name'),'name',S.project.name,'text',120)}<label>${tr('界面语言','Interface language')}<select data-field="settings.language">${selectOptions(['zh','en'],S.project.settings.language,x=>x==='zh'?'简体中文':'English')}</select></label><label>${tr('主题','Theme')}<select data-field="settings.theme">${selectOptions(['warm','light','dark'],S.project.settings.theme,x=>({warm:tr('暖纸绿','Warm paper'),light:tr('明亮','Light'),dark:tr('深色','Dark')})[x])}</select></label><label class="check"><input data-field="settings.autoBuild" type="checkbox" ${S.project.settings.autoBuild?'checked':''}>${tr('修改网站后自动构建（默认关闭）','Auto-build after website edits (off by default)')}</label><small>${tr('构建会写入独立输出目录；不会自动发布，也不会重叠启动多个构建。','Builds write separate outputs. They never publish automatically or overlap each other.')}</small></section><section class="card stack"><h2>${tr('本机与项目文件','Device & project files')}</h2><div class="setting-summary">${S.info?E([S.info.name+' '+S.info.version,'Python '+S.info.pythonVersion,tr('安装根：','Install root: ')+S.info.rootDir,tr('数据目录：','Data directory: ')+S.info.dataDir].join('\n')):tr('浏览器会话：桌面后端尚未连接。','Browser session: desktop backend is not connected.')}</div><div class="actions">${button('import-project',tr('导入 .zthdesk','Import .zthdesk'))}${button('export-project',tr('导出完整项目','Export complete project'))}</div><p class="help-note">${tr('完整项目包含目标、验收、BOM、资料、屏幕模型、私有运营和所有网站图片，采用明文格式。网站 ZIP 只包含公开站点。分享前请确认范围。','A complete plain-text project includes briefs, acceptance, BOM, references, screen models, private operations and site images. Website ZIP contains the public site only. Review the sharing scope.')}</p></section></div>`;}
function dialog(title,body,{submit,submitText,wide=false}={}){document.querySelectorAll('dialog').forEach(x=>x.remove());const d=document.createElement('dialog');if(wide)d.style.width='min(880px,calc(100vw - 36px))';d.innerHTML=`<form method="dialog"><div class="dialog-head"><h2>${title}</h2><button type="button" data-dialog-close aria-label="${tr('关闭','Close')}">×</button></div><div class="dialog-body">${body}<p class="dialog-error" role="alert"></p></div>${submit?`<div class="dialog-actions"><button type="button" data-dialog-close>${tr('取消','Cancel')}</button><button class="primary" type="submit">${submitText||tr('保存','Save')}</button></div>`:''}</form>`;document.body.append(d);d.querySelectorAll('[data-dialog-close]').forEach(b=>b.onclick=()=>d.close());d.addEventListener('close',()=>d.remove());if(submit)d.querySelector('form').onsubmit=async e=>{e.preventDefault();try{await submit(new FormData(e.target));d.close();}catch(err){d.querySelector('.dialog-error').textContent=niceError(err);}};d.showModal();return d;}
function formText(name,label,value='',max=160,kind='text'){return`<label>${label}${kind==='textarea'?`<textarea name="${name}" maxlength="${max}" rows="5">${E(value)}</textarea>`:`<input name="${name}" type="${kind}" value="${E(value)}" maxlength="${max}">`}</label>`;}
function newDialog(){const d=dialog(tr('从哪里开始？','Where would you like to start?'),`<button type="button" class="choice-card" data-new-kind="empty"><strong>${tr('一个空白工作空间','An empty workspace')}</strong><span>${tr('只有首页，从自己的任务和内容开始。','One blank home page. Begin with your own tasks and content.')}</span></button><button type="button" class="choice-card" data-new-kind="demo"><strong>${tr('看看原创示例','Explore the original example')}</strong><span>${tr('青苔工坊：有两页网站、示例任务和私有草稿。全部是虚构内容，可以自由修改。','Moss Workshop: two site pages, sample tasks and private drafts. All content is fictional and editable.')}</span></button>`);d.querySelectorAll('[data-new-kind]').forEach(b=>b.onclick=async()=>{if(!await leaveProject())return;const p=C.newProject({demo:b.dataset.newKind==='demo',language:S.project.settings.language});adopt(p,{dirty:true});d.close();if(bridge())await save().catch(e=>toast(niceError(e)));});}
function taskDialog(id,due=''){const old=S.project.operations.tasks.find(t=>t.id===id),task=old||{id:C.uid('task'),title:'',owner:'',due,status:'idea',channel:'other',notes:'',target:{kind:'none',ref:''}};dialog(old?tr('编辑任务','Edit task'):tr('新建任务','New task'),`<div class="form-grid">${formText('title',tr('任务标题','Task title'),task.title)}${formText('owner',tr('负责人（可空）','Owner (optional)'),task.owner,80)}${formText('due',tr('日期（可空）','Date (optional)'),task.due,10,'date')}<label>${tr('状态','Status')}<select name="status">${selectOptions(['idea','doing','review','done'],task.status,status)}</select></label><label>${tr('渠道','Channel')}<select name="channel">${selectOptions(['web','wechat','canva','event','other'],task.channel,channel)}</select></label></div><label>${tr('关联工作内容（只导航，不执行）','Linked work (navigation only)')}<select name="taskTarget">${targetOptions(task.target)}</select></label>${formText('notes',tr('私有备注','Private notes'),task.notes,8000,'textarea')}${old?button('delete-task',tr('删除此任务','Delete this task'),'danger',`data-id="${E(id)}"`):''}`,{submit:f=>{const values=Object.fromEntries(f),[kind,ref]=String(values.taskTarget||'none:').split(':');delete values.taskTarget;const next={...task,...values,target:{kind,ref:ref||''}};const p=C.clone(S.project);if(old)p.operations.tasks[p.operations.tasks.findIndex(t=>t.id===id)]=next;else p.operations.tasks.push(next);C.validate(p);change(x=>x.operations=p.operations);}});}
function pageDialog(edit=false){const old=edit?getPage():null;dialog(edit?tr('页面设置','Page settings'):tr('新建页面','New page'),`${formText('title',tr('页面标题','Page title'),old?.title||'')}${formText('slug',tr('文件名 · 小写字母/数字/连字符','Filename · lowercase letters/numbers/hyphens'),old?.slug||'',64)}<label class="check"><input type="checkbox" name="nav" ${!old||old.nav?'checked':''}>${tr('显示在网站导航中','Show in site navigation')}</label><p class="help-note">${tr('首页文件名固定为 index。其他页面使用独立 .html 文件，修改文件名后请修正引用它的链接。','The home page slug is index. Other pages are independent .html files. Update links when changing a slug.')}</p>${old&&old.slug!=='index'?button('delete-page',tr('删除页面','Delete page'),'danger'):''}`,{submit:f=>{const p=C.clone(S.project),page=old?p.site.pages.find(x=>x.id===old.id):{id:C.uid('page'),sections:[]};Object.assign(page,{title:String(f.get('title')),slug:old?.slug==='index'?'index':String(f.get('slug')),nav:f.get('nav')==='on'});if(!old)p.site.pages.push(page);C.validate(p);S.page=page.id;S.section='';change(x=>x.site=p.site,{site:true});}});}
function sectionDialog(){const d=dialog(tr('添加一个区块','Add a section'),`<div class="form-grid">${C.TYPES.map(t=>`<button type="button" class="choice-card" data-add-section="${t}"><strong>${type(t)}</strong><span>${({hero:tr('标题、介绍和一个明确的入口','A title, introduction and a clear next step'),text:tr('用段落解释一件事','Explain one thing with paragraphs'),cards:tr('并列介绍几项内容','Introduce related items'),gallery:tr('展示主动加入的图片','Show selected site images'),faq:tr('让常见疑问有明确答案','Answer common questions'),cta:tr('一个清楚的下一步','One clear next step'),contact:tr('公开的联系方式或链接','Public contact details or links')})[t]}</span></button>`).join('')}</div>`);d.querySelectorAll('[data-add-section]').forEach(b=>b.onclick=()=>{const s=C.section(b.dataset.addSection,type(b.dataset.addSection),'');S.section=s.id;change(p=>p.site.pages.find(x=>x.id===getPage().id).sections.push(s),{site:true});d.close();});}
function siteSettings(){dialog(tr('公开网站设置','Public website settings'),`${formText('title',tr('网站标题','Website title'),S.project.site.title)}${formText('description',tr('网站简介','Description'),S.project.site.description,2000,'textarea')}<div class="form-grid"><label>${tr('网站语言','Website language')}<select name="language">${selectOptions(['zh-CN','en'],S.project.site.language,x=>x==='en'?'English':'简体中文')}</select></label><label>${tr('网站样式','Site style')}<select name="theme">${selectOptions(['studio','editorial','portfolio'],S.project.site.theme,x=>({studio:tr('工作室','Studio'),editorial:tr('手记','Editorial'),portfolio:tr('作品集','Portfolio')})[x])}</select></label>${formText('accent',tr('强调色','Accent'),S.project.site.accent,7,'color')}</div>`,{submit:f=>{change(p=>Object.assign(p.site,Object.fromEntries(f)),{site:true});}});}
function assetsDialog(){const d=dialog(tr('公开网站图片','Public website images'),`<p class="help-note">${tr('这里加入的图片属于公开网站，会随网站导出。PNG/JPEG/WebP，每张最多 5 MiB，总共 20 MiB、20 张。不要加入私密图片。','Images added here belong to the public website and are exported with it. PNG/JPEG/WebP, at most 5 MiB each, 20 MiB and 20 images total. Do not add private images.')}</p><label>${tr('明确加入网站图片','Explicitly add a site image')}<input type="file" id="site-image" accept="image/png,image/jpeg,image/webp"></label><div class="asset-grid">${S.project.site.assets.map(a=>`<div class="asset-card"><img src="data:${a.mime};base64,${a.data}" alt="${E(a.alt)}"><small>${E(a.name)}</small><label>${tr('替代文字','Alternative text')}<input data-asset-alt="${E(a.id)}" value="${E(a.alt)}" maxlength="500"></label><button type="button" data-remove-asset="${E(a.id)}">${tr('移除图片','Remove image')}</button></div>`).join('')}</div>`,{wide:true});d.querySelector('#site-image').onchange=async e=>{const f=e.target.files?.[0];if(!f)return;try{if(f.size>C.LIMITS.asset)throw Error('ASSET_LIMIT');const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result).split(',')[1]);r.onerror=reject;r.readAsDataURL(f);});C.magic(data,f.type,'image');const asset={id:C.uid('asset'),name:f.name,mime:f.type,data,alt:''},p=C.clone(S.project);p.site.assets.push(asset);C.validate(p);change(x=>x.site.assets=p.site.assets,{site:true});d.close();assetsDialog();}catch(err){d.querySelector('.dialog-error').textContent=niceError(err);}};}
async function importProject(){if(!await leaveProject())return;if(bridge()){const p=await bridge().importProject();if(p){adopt(p,{dirty:true});await save();toast(tr('已导入并保存；同编号项目会另存副本。','Imported and saved; a matching local ID is stored as a separate copy.'));}}else{const input=document.createElement('input');input.type='file';input.accept='.zthdesk,.json';input.onchange=async()=>{try{const f=input.files?.[0];if(!f)return;if(f.size>C.LIMITS.json)throw Error('PROJECT_LIMIT');adopt(C.validate(await f.text()),{dirty:true});}catch(e){toast(niceError(e));}};input.click();}}
async function action(b){const a=b.dataset.action;if(a==='export-handoff'){await runJob('handoff',{});S.view='jobs';return render();}if(a==='new-bom'||a==='edit-bom')return bomDialog(b.dataset.id);if(a==='new-resource'||a==='edit-resource')return resourceDialog(b.dataset.id);if(a==='delete-bom'||a==='delete-resource'){if(window.confirm(tr('删除这条项目记录？','Delete this project record?'))){const key=a==='delete-bom'?'bom':'resources';change(p=>p.workspace[key]=p.workspace[key].filter(x=>x.id!==b.dataset.id));document.querySelector('dialog')?.close();}return;}if(a==='resource-open'){const r=S.project.workspace.resources.find(x=>x.id===b.dataset.id);if(!r?.url)return;const m=/^(?:\.\/)?([a-z0-9-]+)\.html(?:#(.+))?$/.exec(r.url);if(m){const page=S.project.site.pages.find(x=>x.slug===m[1]);if(!page)throw Error(tr('关联页面已不存在','Linked page no longer exists'));return navigateTarget({kind:'site',ref:page.id});}if(bridge())return bridge().openExternal(r.url);throw Error(tr('请在桌面客户端打开外部资料','Open external references from the desktop client'));}if(a==='new-project')return newDialog();if(a==='save')return save();if(a==='export-project')return exportProject();if(a==='import-project')return importProject();if(a==='language')return change(p=>p.settings.language=p.settings.language==='zh'?'en':'zh');if(a==='new-task')return taskDialog();if(a==='new-draft'){const d={id:C.uid('draft'),title:tr('未命名草稿','Untitled draft'),body:'',tags:[],updatedAt:now()};S.draft=d.id;S.view='drafts';return change(p=>p.operations.drafts.unshift(d));}if(a==='delete-draft'){if(window.confirm(tr('删除这份私有草稿？可用撤销恢复。','Delete this private draft? Undo can restore it.')))change(p=>p.operations.drafts=p.operations.drafts.filter(x=>x.id!==getDraft().id));return;}if(a==='delete-task'){if(window.confirm(tr('删除这项任务？','Delete this task?'))){change(p=>p.operations.tasks=p.operations.tasks.filter(t=>t.id!==b.dataset.id));document.querySelector('dialog')?.close();}return;}if(a==='board-mode'){S.boardMode=b.dataset.mode;return render();}if(a==='month-prev'||a==='month-next'){S.month=new Date(S.month.getFullYear(),S.month.getMonth()+(a==='month-prev'?-1:1),1);return render();}if(a==='new-page')return pageDialog();if(a==='edit-page')return pageDialog(true);if(a==='delete-page'){const p=C.clone(S.project);p.site.pages=p.site.pages.filter(x=>x.id!==getPage().id);C.validate(p);S.page=p.site.pages[0].id;change(x=>x.site=p.site,{site:true});document.querySelector('dialog')?.close();return;}if(a==='new-section')return sectionDialog();if(a==='site-settings')return siteSettings();if(a==='assets')return assetsDialog();if(a==='new-item')return change(p=>p.site.pages.find(x=>x.id===getPage().id).sections.find(x=>x.id===getSection().id).items.push({title:tr('新条目','New item'),body:'',image:'',link:''}),{site:true});if(a==='delete-item')return change(p=>p.site.pages.find(x=>x.id===getPage().id).sections.find(x=>x.id===getSection().id).items.splice(Number(b.dataset.index),1),{site:true});if(['section-up','section-down','delete-section'].includes(a)){const p=C.clone(S.project),page=p.site.pages.find(x=>x.id===getPage().id),index=page.sections.findIndex(x=>x.id===getSection().id);if(a==='delete-section')page.sections.splice(index,1);else{const to=index+(a==='section-up'?-1:1);if(to>=0&&to<page.sections.length)[page.sections[index],page.sections[to]]=[page.sections[to],page.sections[index]];}C.validate(p);change(x=>x.site=p.site,{site:true});return;}if(a==='undo'||a==='redo'){const value=a==='undo'?S.history.undo():S.history.redo();S.project=value;S.dirty=true;S.revision++;scheduleSave();return render();}if(a==='build')return runJob('build',{pageSlug:getPage().slug});if(a.startsWith('run-'))return runJob(a.slice(4),{});if(a==='preview-width'){S.mobile=b.dataset.mobile==='true';return render();}if(a==='copy-site')return bridge().copyOutput(S.buildId);if(a==='refresh-jobs'){const old=new Map(S.jobs.map(j=>[j.id,j]));S.jobs=(await bridge()?.history()||[]).map(j=>({...old.get(j.id),...j}));return render();}if(a==='dns')return runJob('dns',{});if(a==='external'){if(bridge())return bridge().openExternal(b.dataset.url);throw Error(tr('请在桌面客户端打开官方资料','Open documentation from the desktop client'));}if(a==='deploy'){if(!S.buildId||S.previewRevision!==S.revision)throw Error(tr('当前内容尚未构建，请先重新构建并检查预览','Current content has not been built. Rebuild and inspect the preview first'));const token=$('#publish-token').value,owner=$('#publish-owner').value.trim(),repo=$('#publish-repo').value.trim(),consent=$('#publish-consent').checked;if(!consent||!token||!owner||!repo)throw Error(tr('请填写仓库和本次令牌，并确认公开范围','Fill the repository and invocation token, then confirm the public scope'));$('#publish-token').value='';await runJob('deploy',{owner,repo,token,domain:S.project.site.domain,confirmPublic:true});S.view='jobs';return render();}}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;(async()=>{if(integrationHandle?.flush)await integrationHandle.flush();if(b.dataset.taskTarget){const t=S.project.operations.tasks.find(x=>x.id===b.dataset.taskTarget);return navigateTarget(t?.target);}if(b.dataset.view){S.view=b.dataset.view;return render();}if(b.dataset.openDraft){S.draft=b.dataset.openDraft;S.view='drafts';return render();}if(b.dataset.editTask)return taskDialog(b.dataset.editTask);if(b.dataset.addDate)return taskDialog('',b.dataset.addDate);if(b.dataset.page){S.page=b.dataset.page;S.section='';return render();}if(b.dataset.section){S.section=b.dataset.section;return render();}if(b.dataset.cancelJob){await bridge().cancel(b.dataset.cancelJob);startPolling();toast(tr('取消请求已提交。已完成的远端操作不会回滚。','Cancellation requested. Completed remote actions are not rolled back.'));return;}if(b.dataset.openJob)return bridge().openOutput(b.dataset.openJob);if(b.dataset.copyJob)return bridge().copyOutput(b.dataset.copyJob);if(b.dataset.removeAsset){const id=b.dataset.removeAsset,p=C.clone(S.project);p.site.assets=p.site.assets.filter(a=>a.id!==id);for(const page of p.site.pages)for(const s of page.sections){if(s.image===id)s.image='';for(const item of s.items)if(item.image===id)item.image='';}change(x=>x.site=p.site,{site:true});assetsDialog();return;}if(b.dataset.action)return action(b);})().catch(err=>toast(niceError(err)));});
function editField(e,rerender=false){const target=e.target,path=target.dataset.field;if(!path)return;const value=target.type==='checkbox'?target.checked:target.value;change(p=>{setPath(p,path,value);if(path.startsWith('operations.drafts.'))p.operations.drafts[Number(path.split('.')[2])].updatedAt=now();},{renderPage:rerender,remember:rerender,site:path.startsWith('site.')});if(path==='settings.autoBuild'&&!value){clearTimeout(buildTimer);S.pendingBuild=false;}}
document.addEventListener('input',e=>{if(e.target.id==='publish-owner'){const target=$('[data-cname-target]'),owner=e.target.value.trim();if(target)target.textContent=/^[A-Za-z0-9](?:[A-Za-z0-9-]{0,37}[A-Za-z0-9])?$/.test(owner)?owner.toLowerCase()+'.github.io':'your-account.github.io';}if(e.target.matches('input[data-field],textarea[data-field]')&&e.target.type!=='checkbox')try{editField(e);}catch(err){toast(niceError(err));}});
document.addEventListener('change',e=>{const t=e.target;(async()=>{if(t.dataset.project)return loadProject(t.value);if(t.dataset.field)return editField(e,true);if(t.dataset.taskStatus)return change(p=>p.operations.tasks.find(x=>x.id===t.dataset.taskStatus).status=t.value);if(t.dataset.draftTags)return change(p=>{const d=p.operations.drafts.find(x=>x.id===t.dataset.draftTags);d.tags=t.value.split(',').map(x=>x.trim()).filter(Boolean);d.updatedAt=now();});if(t.dataset.assetAlt)return change(p=>p.site.assets.find(a=>a.id===t.dataset.assetAlt).alt=t.value,{renderPage:false,site:true});})().catch(err=>toast(niceError(err)));});
window.addEventListener('beforeunload',e=>{if(S.dirty||S.saving){e.preventDefault();e.returnValue='';}});window.addEventListener('pagehide',()=>{clearTimeout(saveTimer);clearTimeout(buildTimer);clearTimeout(pollTimer);S.closing=true;});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();save().catch(err=>toast(niceError(err)));}if(e.key==='Escape')$('#publish-token')&&($('#publish-token').value='');});
window.DeskApp={navigate:navigateTarget,updateWorkspace:fn=>change(p=>{fn(p.workspace);C.validate(p);},{renderPage:false}),getProject:()=>C.clone(S.project),getState:()=>({view:S.view,dirty:S.dirty,saving:S.saving,revision:S.revision,previewRevision:S.previewRevision,jobs:C.clone(S.jobs)}),setProject:p=>adopt(p,{dirty:true}),save,runJob,render,get initialized(){return initialized;}};
async function init(){S.history=new C.History(S.project);render();if(bridge()){try{const values=await Promise.all([bridge().info(),bridge().list(),bridge().history()]);S.info=values[0];S.projects=values[1];S.jobs=values[2]||[];if(S.projects.length)adopt(await bridge().load(S.projects[0].id));else{render();newDialog();}if(S.jobs.some(j=>j.status==='running'))startPolling();}catch(e){S.saveError=niceError(e);toast(S.saveError);}}else{S.saveError=tr('浏览器会话：请导出项目保存','Browser session: export your project to save');newDialog();}initialized=true;updateSave();}
// Workspace v2: one project owns plans, materials, screen design and public pages.
function money(n){return Number(n).toLocaleString(lang(),{maximumFractionDigits:2});}
function stageLink(view,index,title,body,complete){return`<button class="flow-step ${complete?'ready':''}" data-view="${view}"><span class="step-number">${index}</span><strong>${title}</strong><small>${body}</small><span class="step-state">${complete?tr('已有内容','Started'):tr('从这里开始','Start here')} →</span></button>`;}
function overview2(){const p=S.project,w=p.workspace,open=p.operations.tasks.filter(x=>x.status!=='done'),total=C.bomTotals(p);return head(tr('把想法做成，看得见的成果。','Give an idea a useful form.'),tr('目标、制作、环境、记录与发布，共用一个项目。','One project for purpose, making, environment, notes and publishing.'))+`<section class="project-hero"><div><span class="badge private">${tr('当前本地项目','CURRENT LOCAL PROJECT')}</span><h2>${E(p.name)}</h2><p>${E(w.brief.trim()?w.brief.slice(0,190):tr('先写清要解决的问题，再用实际作品和验收记录回答它。','Describe the problem first. Answer it with a working artifact and recorded checks.'))}</p><div class="actions"><button class="primary" data-view="workspace">${w.brief?tr('查看目标与验收','Review brief & acceptance'):tr('写下项目目标','Write the project brief')} →</button><button data-view="operations">${tr('安排下一步','Plan the next step')}</button>${button('export-handoff',tr('导出交接包 · 私有','Project handoff · private'),'',!bridge()?'disabled':'')}</div></div><div class="project-snapshot"><span>${E(new Date().toLocaleDateString(lang(),{month:'short',day:'numeric',weekday:'short'}))}</span><strong>${open.length}<small>${tr('项待完成','OPEN TASKS')}</small></strong><p>${total.items} ${tr('项物料','BOM items')} · ${p.site.pages.length} ${tr('页网站','site pages')}</p></div></section><div class="flow-header"><h2>${tr('同一个项目，一条完整路径','A connected project workflow')}</h2><small>${tr('按需要进入，完成状态由你验收。','Enter where useful. Acceptance remains your decision.')}</small></div><section class="project-flow">${stageLink('workspace','01',tr('定义目标','Define'),tr('问题、范围与验收','Brief, scope & acceptance'),!!w.brief.trim())}${stageLink('bom','02',tr('准备材料','Prepare'),tr('BOM、资料与成本','BOM, references & cost'),!!w.bom.length)}${stageLink('screen','03',tr('制作界面','Make'),tr('设备屏幕与代码','Device screen & code'),!!w.screen)}${stageLink('environment','04',tr('准备环境','Set up'),tr('查看计划，再决定执行','Review before running'),w.resources.some(x=>x.kind==='environment'))}${stageLink('site','05',tr('记录与展示','Share'),tr('草稿、网页与主动发布','Draft, build & publish'),p.site.pages.some(x=>x.sections.length))}</section><div class="two-col"><section class="card"><div class="card-head"><h2>${tr('接下来要做','Next actions')}</h2>${button('new-task',tr('＋ 任务','＋ Task'))}</div>${open.slice(0,4).map(taskRow).join('')||empty(tr('留下一项具体行动','Choose one concrete action'),tr('任务可直接关联屏幕、网页、草稿或环境计划。','Tasks can link to a screen, page, draft or environment plan.'),'new-task')}</section><section class="card"><div class="card-head"><h2>${tr('项目资料','Project files')}</h2><button data-view="resources">${tr('查看资料','References')} →</button></div><div class="project-file"><span>◈</span><div><strong>${tr('屏幕设计','Screen design')}</strong><p>${E(w.screen?.name||tr('尚未创建；可在项目中继续编辑','Not created yet; edit it inside this project'))}</p></div><button data-view="screen">${tr('打开','Open')}</button></div><div class="project-file"><span>≡</span><div><strong>${tr('私有草稿','Private drafts')}</strong><p>${p.operations.drafts.length} ${tr('篇，不会自动进入网站','drafts, excluded from website exports')}</p></div><button data-view="drafts">${tr('写作','Write')}</button></div><div class="help-note">${tr('完整 .zthdesk 保存所有项目资料；网站 ZIP 仅导出公开网站。环境安装与发布都需要你主动确认。','A full .zthdesk retains the entire project; website ZIP contains only the public site. Environment changes and publishing need your explicit confirmation.')}</div></section></div>`;}
function workspaceView(){return head(tr('先说清楚，什么叫做好。','Define what good means.'),tr('这些是私有项目说明。用可以检查的结果约定范围，而不只是列功能。','Private project notes. Define observable outcomes, not only a feature list.'))+`<div class="brief-grid"><section class="card stack">${field(tr('项目目标与范围','Project brief & scope'),'workspace.brief',S.project.workspace.brief,'textarea',20000,'class="brief-editor" placeholder="'+tr('例如：做一个桌面环境屏，显示温度和电量；本轮不接入云服务。','Example: a desk display showing temperature and battery. Cloud services are outside this iteration.')+'"')}<small>${tr('写明给谁用、解决什么问题、有哪些已知约束。','Who is it for, what problem does it solve, and what constraints are known?')}</small></section><section class="card stack">${field(tr('验收标准与实际记录','Acceptance criteria & evidence'),'workspace.acceptance',S.project.workspace.acceptance,'textarea',20000,'class="brief-editor" placeholder="'+tr('例如：断开传感器时显示错误；重新开机后布局不丢失；记录观察结果。','Example: show an error on sensor disconnect; preserve layout after restart; record what was observed.')+'"')}<small>${tr('软件预览、代码编译和实际硬件效果是不同的验收，不自动互相替代。','Preview, code compilation and real hardware are separate acceptance steps.')}</small></section></div><div class="workspace-next card"><div><h3>${tr('把下一步落到任务上','Turn the next step into a task')}</h3><p>${tr('为任务选择关联内容，以后可以直接回到制作的位置。','Link a task to its working context so you can return directly.')}</p></div><div class="actions">${button('new-task',tr('＋ 添加关联任务','＋ Add linked task'),'primary')}${button('export-handoff',tr('导出项目交接包','Export project handoff'),'',!bridge()?'disabled':'')}</div></div><p class="help-note" style="margin-top:15px">${tr('交接包包含目标、验收、任务、BOM、资料、草稿及可编辑模型，是私有完整交接；它不是公开网站 ZIP。','The handoff includes brief, acceptance, tasks, BOM, references, drafts and editable models. It is a private full-project handoff, not the public website ZIP.')}</p>`;}
const bomStatus=v=>({needed:tr('待准备','Needed'),ordered:tr('已订购','Ordered'),ready:tr('已就绪','Ready')})[v];
const resourceKind=v=>({reference:tr('参考资料','Reference'),design:tr('设计资料','Design'),learning:tr('学习资料','Learning'),environment:tr('环境计划','Environment')})[v];
function bomView(){const w=S.project.workspace,t=C.bomTotals(S.project);return head(tr('材料清楚，制作更从容。','Know the parts before the build.'),tr('数量与单价计算预算；请保持同一种货币。采购状态由你更新。','Quantity × unit cost gives the estimate; use one currency consistently. Update procurement status yourself.'),button('new-bom',tr('＋ 添加物料','＋ Add part'),'primary'))+`<div class="bom-summary"><div><span>${tr('预算合计','ESTIMATED TOTAL')}</span><strong>${money(t.total)}</strong></div><p>${t.ready} / ${t.items} ${tr('项已就绪','items ready')}<br><small>${tr('不含未填写成本、运费或税费。','Excludes unspecified costs, shipping and tax.')}</small></p></div>${w.bom.length?`<section class="card bom-table"><div class="bom-table-head"><span>${tr('物料 / 备注','PART / NOTES')}</span><span>${tr('数量 × 单价','QTY × UNIT COST')}</span><span>${tr('小计','SUBTOTAL')}</span><span>${tr('状态与操作','STATUS / ACTIONS')}</span></div>${w.bom.map(x=>`<article class="bom-row"><div><h3>${E(x.name)}</h3><p>${E(x.notes.slice(0,120))}</p></div><span>${money(x.quantity)} ${E(x.unit)} × ${money(x.unitCost)}</span><strong>${money(x.quantity*x.unitCost)}</strong><div class="actions"><span class="badge">${bomStatus(x.status)}</span>${button('edit-bom',tr('编辑','Edit'),'',`data-id="${E(x.id)}"`)}${x.link?button('external',tr('资料','Link'),'',`data-url="${E(x.link)}"`):''}</div></article>`).join('')}</section>`:empty(tr('从关键物料开始','Start with the important parts'),tr('记录具体型号、数量、单价，以及已核对的资料链接。','Record the exact part, quantity, price and a reviewed reference link.'),'new-bom')}`;}
function bomDialog(id){const old=S.project.workspace.bom.find(x=>x.id===id),x=old||{id:C.uid('part'),name:'',quantity:1,unit:tr('个','pcs'),unitCost:0,status:'needed',link:'',notes:''};dialog(old?tr('编辑物料','Edit part'):tr('添加物料','Add part'),`<div class="form-grid">${formText('name',tr('型号或名称','Part number or name'),x.name,240)}${formText('unit',tr('单位','Unit'),x.unit,32)}${formText('quantity',tr('数量','Quantity'),x.quantity,32,'number')}${formText('unitCost',tr('单价','Unit cost'),x.unitCost,32,'number')}<label>${tr('状态','Status')}<select name="status">${selectOptions(['needed','ordered','ready'],x.status,bomStatus)}</select></label>${formText('link',tr('公开 HTTPS 资料链接（可空）','Public HTTPS reference (optional)'),x.link,2048)}</div>${formText('notes',tr('私有备注','Private notes'),x.notes,4000,'textarea')}${old?button('delete-bom',tr('删除物料','Delete part'),'danger',`data-id="${E(id)}"`):''}`,{submit:f=>{const next={...x,...Object.fromEntries(f),quantity:Number(f.get('quantity')),unitCost:Number(f.get('unitCost'))};if(!String(f.get('quantity')).trim()||!String(f.get('unitCost')).trim())throw Error(tr('请填写有效数量和单价','Enter a valid quantity and unit cost'));const p=C.clone(S.project);if(old)p.workspace.bom[p.workspace.bom.findIndex(x=>x.id===id)]=next;else p.workspace.bom.push(next);C.validate(p);change(x=>x.workspace=p.workspace);}});for(const el of document.querySelectorAll('dialog input[type=number]')){el.min='0';el.step='any';}}
function resourcesView(){const items=S.project.workspace.resources;return head(tr('把有用的线索，留在项目旁。','Keep useful references with the project.'),tr('链接与笔记是私有资料。环境计划只保存说明，打开或导入不会执行安装。','Links and notes stay private. Environment references store context; opening or importing never runs an installation.'),button('new-resource',tr('＋ 添加资料','＋ Add reference'),'primary'))+(items.length?`<div class="resource-grid">${items.map(x=>`<article class="card resource-card"><span class="badge private">${resourceKind(x.kind)}</span><h3>${E(x.title)}</h3><p>${E(x.notes.slice(0,320))}</p><small>${E(x.url||tr('仅项目笔记','Project note only'))}</small><div class="actions">${button('edit-resource',tr('编辑','Edit'),'',`data-id="${E(x.id)}"`)}${x.url?button('resource-open',tr('打开资料','Open reference'),'',`data-id="${E(x.id)}"`):''}${x.kind==='environment'?`<button data-view="environment">${tr('查看环境工作区','Environment workspace')} →</button>`:''}</div></article>`).join('')}</div>`:empty(tr('资料跟着项目走','References travel with the project'),tr('保存官方文档、设计说明、学习入口或环境计划摘要。','Keep documentation, design notes, learning links or environment plan summaries.'),'new-resource'));}
function resourceDialog(id){const old=S.project.workspace.resources.find(x=>x.id===id),x=old||{id:C.uid('resource'),title:'',url:'',kind:'reference',notes:''};dialog(old?tr('编辑资料','Edit reference'):tr('添加资料','Add reference'),`${formText('title',tr('资料标题','Title'),x.title,240)}<label>${tr('类型','Kind')}<select name="kind">${selectOptions(['reference','design','learning','environment'],x.kind,resourceKind)}</select></label>${formText('url',tr('链接（可空）','Link (optional)'),x.url,2048)}${formText('notes',tr('私有笔记或计划摘要','Private notes or plan summary'),x.notes,8000,'textarea')}${old?button('delete-resource',tr('删除资料','Delete reference'),'danger',`data-id="${E(id)}"`):''}`,{submit:f=>{const next={...x,...Object.fromEntries(f)},p=C.clone(S.project);if(old)p.workspace.resources[p.workspace.resources.findIndex(x=>x.id===id)]=next;else p.workspace.resources.push(next);C.validate(p);change(x=>x.workspace=p.workspace);}});}
function integrationView(view){return head(view==='screen'?tr('设计设备上的每一屏。','Design the screen on your device.'):tr('先看清计划，再准备环境。','Review the plan, then prepare the environment.'),view==='screen'?tr('屏幕模型保存到当前项目。代码另行导出，实机效果需要独立验证。','The screen model belongs to this project. Export code separately and verify real hardware.'):tr('检查与执行都由你主动发起；任务不因切换页面而丢失。','Detection and execution are explicit actions; jobs survive navigation.'))+`<section id="desk-integration" class="integration-host" aria-live="polite"><div class="empty">${tr('正在准备项目工具…','Preparing the project tools…')}</div></section>`;}
function mountIntegration(){if(!['screen','environment'].includes(S.view))return;const container=$('#desk-integration'),api=window.DeskIntegrations;if(!api?.mount){container.innerHTML=empty(tr('集成模块未载入','Integration module unavailable'),tr('项目资料仍已保留。请核对完整安装包。','Project data is preserved. Check that the complete app was installed.'));return;}try{const mountedProject=S.project.id;let active=true;const handle=api.mount({view:S.view,container,project:C.clone(S.project),getProject:()=>C.clone(S.project),onScreenChange:model=>{if(!active||S.project.id!==mountedProject)return false;const safe=C.screenModel(model);if(JSON.stringify(safe)!==JSON.stringify(S.project.workspace.screen))change(p=>p.workspace.screen=safe,{renderPage:false});return true;},onResource:resource=>{if(!active||S.project.id!==mountedProject)return false;const p=C.clone(S.project),v={...resource,id:resource.id||C.uid('resource')},index=p.workspace.resources.findIndex(x=>x.id===v.id);if(index<0)p.workspace.resources.push(v);else p.workspace.resources[index]=v;C.validate(p);change(x=>x.workspace=p.workspace,{renderPage:false});},navigate:navigateTarget,language:S.project.settings.language,theme:S.project.settings.theme,bridge:bridge()});integrationHandle={flush:()=>handle?.flush?.(),update:value=>handle?.update?.(value),dispose:()=>{active=false;typeof handle==='function'?handle():handle?.dispose?.();}};}catch(e){container.textContent=niceError(e);}}
function navigateTarget(target){const kind=target?.kind,ref=target?.ref||'';if(kind==='site'){const p=S.project.site.pages.find(x=>x.id===ref);if(ref&&!p)return toast(tr('关联页面已不存在，请重新选择任务关联。','Linked page no longer exists. Update the task target.'));S.page=p?.id||S.project.site.pages[0].id;S.section='';S.view='site';}else if(kind==='draft'){const d=S.project.operations.drafts.find(x=>x.id===ref);if(ref&&!d)return toast(tr('关联草稿已不存在，请重新选择任务关联。','Linked draft no longer exists. Update the task target.'));S.draft=d?.id||'';S.view='drafts';}else if(kind==='screen'||kind==='environment'){S.view=kind;}else return;render();}
function targetOptions(selected={kind:'none',ref:''}){const options=[['none:',tr('不关联','No link')],['screen:',tr('当前项目的屏幕设计','This project’s screen design')],['environment:',tr('环境工作区','Environment workspace')],...S.project.site.pages.map(p=>['site:'+p.id,tr('网页 · ','Page · ')+p.title]),...S.project.operations.drafts.map(d=>['draft:'+d.id,tr('草稿 · ','Draft · ')+d.title]),...S.project.workspace.resources.filter(r=>r.kind==='environment').map(r=>['environment:'+r.id,tr('环境资料 · ','Environment reference · ')+r.title])];const current=selected.kind+':'+selected.ref;if(!options.some(x=>x[0]===current))options.push([current,tr('原关联（可能已移除）','Previous link (may be removed)')]);return options.map(([value,label])=>`<option value="${E(value)}" ${value===current?'selected':''}>${E(label)}</option>`).join('');}
function taskTargetButton(task){return task.target?.kind&&task.target.kind!=='none'?`<button class="task-context" data-task-target="${E(task.id)}">${tr('打开关联','Open linked work')} ↗</button>`:'';}
function help2(){return head(tr('赋形造物工作室','Fuxing Zaowu Studio'),tr('向阳科创工作室旗下的子工作室。','A sub-studio of Xiangyang Science & Technology Studio.'))+`<section class="about-studio card"><img src="logo.svg" alt="${tr('赋形造物标志','Studio mark')}"><div><p class="eyebrow">ZTH STUDIO DESK · 2.0.0</p><h2>${tr('赋形造物工作台','ZTH Studio Desk')}</h2><p>${tr('把工程学习、动手制作与工作室运营放进同一个工作流程。','Bring engineering learning, making and studio operations into one workflow.')}</p></div></section><div class="two-col"><section class="card prose"><h2>${tr('创作者','Creator')}</h2><h3>${tr('理工阿白菌','理工阿白菌')} <small>阿白菌 / TechABJ</small></h3><p>${tr('本软件由理工阿白菌为工作室制作，关注能把工程学习、动手制作与日常运营连接起来的工具。','Created by 理工阿白菌 (阿白菌 / TechABJ) for the studio, with a focus on tools connecting engineering learning, making and daily operations.')}</p><p>© 2026 ${tr('理工阿白菌（阿白菌 / TechABJ）','理工阿白菌 (阿白菌 / TechABJ)')} · zeruik@qq.com</p><p>${tr('代码继续采用 MIT 许可；原始工作室图形标识的权利单独保留。','Code remains MIT licensed; original studio artwork rights are retained separately.')}</p></section><section class="card prose"><h2>${tr('怎么用这一个项目','How one project connects the work')}</h2><ol><li>${tr('定义目标与验收，建立任务和 BOM。','Write the brief and acceptance criteria; plan tasks and parts.')}</li><li>${tr('在项目中设计屏幕、导出代码，明确检查环境计划。','Design screens and export code; explicitly review environment plans.')}</li><li>${tr('把过程留成草稿，再选择可以公开的网站内容。','Keep private notes, then select what belongs on the public website.')}</li><li>${tr('构建实际网页、检查预览，主动确认后发布。','Build actual pages, inspect the preview, then explicitly publish.')}</li></ol></section></div><section class="card prose about-boundary"><h2>${tr('数据与执行边界','Data and execution boundaries')}</h2><p>${tr('完整 .zthdesk 是明文项目文件，包含目标、验收、物料、资料、屏幕模型、私有任务和草稿。它与学院加密的 .zth 不同。网站 ZIP 仅包含公开 site 内容；不会夹带上述私有资料。','A full .zthdesk is a plain project file containing briefs, acceptance notes, BOM, references, screen models, private tasks and drafts. It differs from the Academy’s encrypted .zth. Website ZIP includes only public site content.')}</p><p>${tr('加载项目、点击任务关联或切换视图，不会自动安装环境或发布网站。实际环境操作与 GitHub 发布由原生窗口确认；取消不能撤销已经完成的外部改动。','Loading projects, opening task links and switching views do not install environments or publish sites. Actual environment actions and GitHub publishing require native confirmation; cancellation cannot undo completed external changes.')}</p><p>${tr('所有运行时与存档跟随安装目录，更新前导出备份。保存失败会保留未保存状态；实机接线、显示效果和完整环境仍需要各自验证。','Runtimes and data follow the installation directory. Export backups before updates. Save failures retain the unsaved state; physical wiring, display behavior and complete environments require their own verification.')}</p></section>`;}
init();
})();
